import { json } from "@sveltejs/kit";
import { P as PRIVATE_PAYPAY_API_URL, a as PRIVATE_PAYPAY_SALE_PRODUCT_CODE, b as PRIVATE_PAYPAY_PUBLIC_KEY, c as PRIVATE_PAYPAY_PRIVATE_KEY, d as PRIVATE_PAYPAY_PARTNER_ID } from "../../../../../../chunks/private.js";
import { P as PayPaySDK } from "../../../../../../chunks/index3.js";
const config = {
  partnerId: PRIVATE_PAYPAY_PARTNER_ID,
  privateKey: PRIVATE_PAYPAY_PRIVATE_KEY,
  paypayPublicKey: PRIVATE_PAYPAY_PUBLIC_KEY,
  language: "pt",
  saleProductCode: PRIVATE_PAYPAY_SALE_PRODUCT_CODE,
  apiUrl: PRIVATE_PAYPAY_API_URL
};
const sdk = new PayPaySDK(config);
const POST = async ({ request }) => {
  try {
    const { amount, subject = "Compra" } = await request.json();
    const req = {
      outTradeNo: PayPaySDK.generateUniqueOrderNo("REF"),
      amount,
      subject
    };
    const res = await sdk.createReferencePayment(req);
    if (res.code !== "S0001") {
      return json({
        message: "Erro ao processar pagamento por referência",
        status: "error",
        error: res.message
      }, { status: 500 });
    }
    return json({
      message: "Referencia criada com sucesso",
      status: "success",
      transactionId: res.biz_content?.out_trade_no,
      outTradeNo: res.biz_content?.out_trade_no,
      entidade: res.biz_content?.entity_id,
      referencia: res.biz_content?.reference_id,
      amount,
      subject
    });
  } catch (error) {
    console.error("PayPay Reference Payment Error:", error);
    return json({
      message: "Erro ao processar pagamento por referência",
      status: "error",
      error: error.message
    }, { status: 500 });
  }
};
export {
  POST
};
